import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"提交 BUG","description":"GitHub Issues。填写复现步骤、期望与实际、版本、平面、打码日志。先开 Issue，再开绑定它的 PR。","frontmatter":{"title":"提交 BUG","description":"GitHub Issues。填写复现步骤、期望与实际、版本、平面、打码日志。先开 Issue，再开绑定它的 PR。"},"headers":[],"relativePath":"contribute/bugs.md","filePath":"contribute/bugs.md","lastUpdated":1790057721000}`),a={name:`contribute/bugs.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="提交-bug" tabindex="-1">提交 BUG <a class="header-anchor" href="#提交-bug" aria-label="Permalink to “提交 BUG”">​</a></h1><p>打开 <a href="https://github.com/Kirizu-Official/KiriVers/issues/new" target="_blank" rel="noreferrer">https://github.com/Kirizu-Official/KiriVers/issues/new</a>。Issue 表单模板在仓库 <code>.github/ISSUE_TEMPLATE/</code>。</p><p>建议填写：</p><ol><li>可复现步骤</li><li>期望与实际</li><li>二进制版本或 commit（Release 包名 <code>KiriVers-&lt;OS&gt;-&lt;Arch&gt;-&lt;sha6&gt;.zip</code> 末尾那六位可以唯一定位那次发版；自编译请注明 commit）</li><li>操作系统</li><li>访问的是客户端平面（<code>:8080</code>）还是管理平面（<code>:8081</code>）</li><li>相关日志（打码密钥、Token、DSN 密码）</li></ol><p>安全类漏洞不要开公开 Issue。仓库公开后见 SECURITY；在此之前私下联系维护者。</p><h2 id="顺序-先-issue-再-pr" tabindex="-1">顺序：先 Issue，再 PR <a class="header-anchor" href="#顺序-先-issue-再-pr" aria-label="Permalink to “顺序：先 Issue，再 PR”">​</a></h2><p>Issue 是流程的起点，修复它的 PR 必须回指这个 Issue：</p><ol><li>先开 Issue，把复现信息写全（上面那六项）。</li><li>确认要改后，从默认分支拉功能分支，开 PR 并绑定该 Issue：侧栏 <strong>Development → Link an issue</strong>，或在 PR 描述里写 <code>Fixes #&lt;编号&gt;</code>（<code>Closes</code> / <code>Resolves</code> 同样有效）。</li><li>确实不需要 Issue 的 PR（例如维护者自己的整理改动）加 <code>skip-issue-check</code> 标签。</li></ol><p>这道门只卡<strong>进 <code>main</code> 的 PR</strong>；守卫 bot 的判定与豁免见 <a href="/contribute/pull-requests">贡献代码</a>。</p>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};